        int[] t = new int[5];
        Arrays.fill(t, -1);
        int[] keys = {5, 10, 15};
        for (int k : keys) {
            int i = k % 5;
            while (t[i] != -1) i = (i + 1) % 5;
            t[i] = k;
        }
        System.out.println(Arrays.toString(t));
    }
